package com.oms.supplychain.service.wms;

import org.springframework.stereotype.Component;
import org.w3c.dom.Element;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.stream.Collectors;
import static com.oms.supplychain.service.wms.WmsStore.*;

/** Official white paper 5.6-8, 5.13-15, 5.32, 5.34-35, 5.38. No sales/platform order identities. */
@Component public class QimenWarehouseControlProtocol {
 private static final DateTimeFormatter TIME=DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");
 private String v(Element e,String k){Element a=e==null?null:QimenProtocol.child(e,k);return a==null?"":a.getTextContent().trim();}
 private long qty(String a,boolean signed){try{long q=new java.math.BigDecimal(a).longValueExact();require(q>=-100000000&&q<=100000000&&(signed||q>=0),"数量无效");return q;}catch(Exception e){throw new IllegalArgumentException("仓库数量须为有效整数，缺失不能按零处理");}}
 private String xml(Map<String,Object>req){StringBuilder b=new StringBuilder("<request>");req.forEach((k,v)->append(b,k,v));return b.append("</request>").toString();}
 private void append(StringBuilder b,String key,Object value){if(value instanceof Map){b.append('<').append(key).append('>');((Map<?,?>)value).forEach((k,v)->append(b,k.toString(),v));b.append("</").append(key).append('>');}else if(value instanceof List){if(key.equals("orderLines")){b.append("<orderLines>");for(Object v:(List<?>)value)append(b,"orderLine",v);b.append("</orderLines>");}else for(Object v:(List<?>)value)append(b,key,v);}else b.append(QimenProtocol.tag(key,value));}
 public static boolean matches(String body){try{Element r=QimenProtocol.parse(body),h=QimenProtocol.child(r,"deliveryOrder");String key=h==null?"entryOrderCode":"deliveryOrderCode";if(h==null)h=QimenProtocol.child(r,"entryOrder");Element code=h==null?null:QimenProtocol.child(h,key);return code!=null&&code.getTextContent().matches("DB[OIH][a-f0-9]{32}");}catch(Exception e){return false;}}
 public WmsProtocol.Wire wire(Map<String,Object>c,String secret,String method,Map<String,Object>req){require("QIMEN".equals(c.get("provider"))&&"2.0".equals(text(c.get("api_version"))),"本功能需要奇门2.0连接");String body=xml(req);Map<String,String>p=new TreeMap<>();p.put("app_key",text(c.get("app_key")));p.put("customerId",text(c.get("customer_id")));p.put("method","taobao.qimen."+method);p.put("v","2.0");p.put("format","xml");p.put("sign_method","md5");p.put("timestamp",LocalDateTime.now(ZoneId.of("Asia/Shanghai")).format(TIME));p.put("sign",QimenProtocol.sign(p,body,secret));return new WmsProtocol.Wire(text(c.get("endpoint"))+"?"+p.entrySet().stream().map(e->QimenProtocol.enc(e.getKey())+"="+QimenProtocol.enc(e.getValue())).collect(Collectors.joining("&")),body,"application/xml;charset=UTF-8");}
 public void verify(Map<String,Object>c,String secret,Map<String,String>p,String body,String method){require(("taobao.qimen."+method).equals(p.get("method"))&&"md5".equals(p.get("sign_method"))&&"2.0".equals(p.get("v"))&&text(c.get("api_version")).equals("2.0"),"仓库回传方法、版本或签名算法不匹配");require(text(c.get("app_key")).equals(p.get("app_key"))&&text(c.get("customer_id")).equals(p.get("customerId")),"回传应用不匹配");LocalDateTime t;try{t=LocalDateTime.parse(p.get("timestamp"),TIME);}catch(Exception e){throw new IllegalArgumentException("回传时间格式无效");}require(Math.abs(Duration.between(t,LocalDateTime.now(ZoneId.of("Asia/Shanghai"))).getSeconds())<=600,"回传已过期");require(java.security.MessageDigest.isEqual(QimenProtocol.sign(p,body,secret).getBytes(StandardCharsets.UTF_8),text(p.get("sign")).getBytes(StandardCharsets.UTF_8)),"仓库回传验签失败");}
 public WmsProtocol.Wire transfer(Map<String,Object>c,String secret,String action,Map<String,Object>e,Map<String,Object>route,List<Map<String,Object>>lines){boolean out="OUT".equals(e.get("side"));String kind=out?"stockout":"entryorder",code=out?"deliveryOrderCode":"entryOrderCode",ext=out?"deliveryOrderId":"entryOrderId";Map<String,Object>req;
  if(action.equals("CREATE")){Map<String,Object>h=map(code,e.get("document_sn"),"orderType",out?"DBCK":"DBRK","warehouseCode",route.get("external_warehouse"),"ownerCode",route.get("external_owner"),out?"createTime":"orderCreateTime",text(e.get("create_time")).replace('T',' ').substring(0,19),"totalOrderLines",lines.size(),"remark","同公司同货主跨实仓调拨；业务单 "+e.get("transfer_sn"));if(out){h.put("receiverInfo",route.get("receiver"));h.put("targetEntryOrderCode",e.get("target_entry_sn"));h.put("relatedOrders",map("relatedOrder",map("orderType","DB","orderCode",e.get("transfer_sn"))));}else {h.put("relatedOrders",map("relatedOrder",map("orderType","DB","orderCode",e.get("transfer_sn"))));h.put("logisticsCode",e.get("carrier_code"));h.put("expressCode",e.get("waybill"));}List<Map<String,Object>>ls=new ArrayList<>();for(Map<String,Object>l:lines)ls.add(map("orderLineNo",l.get("line_key"),"ownerCode",route.get("external_owner"),"itemCode",l.get("sku_sn"),"itemName",l.get("goods_name"),"inventoryType","CP".equals(l.get("inventory_type"))?"CC":"ZP","planQty",l.get("quantity"),"batchCode",l.get("batch_code"),"purchasePrice",l.get("unit_cost"),"unit",l.get("stock_unit")));req=map(out?"deliveryOrder":"entryOrder",h,"orderLines",ls);}
  else if(action.equals("QUERY"))req=map("warehouseCode",route.get("external_warehouse"),"ownerCode",route.get("external_owner"),code,e.get("document_sn"),ext,e.get("external_order"),"page",1,"pageSize",100);
  else{require(action.equals("CANCEL"),"未知调拨交互动作");req=map("warehouseCode",route.get("external_warehouse"),"ownerCode",route.get("external_owner"),"orderCode",e.get("document_sn"),"orderId",e.get("external_order"),"orderType",out?"DBCK":"DBRK","cancelReason","停止尚未实际出库或收货的剩余部分");}
  return wire(c,secret,action.equals("CANCEL")?"order.cancel":kind+"."+action.toLowerCase(Locale.ROOT),req);
 }
 public WmsProtocol.Reply reply(boolean out,String body){Element root=QimenProtocol.parse(body);require("response".equals(root.getTagName())&&Arrays.asList("success","failure").contains(v(root,"flag")),"仓库没有返回明确结果");WmsProtocol.Reply r=new WmsProtocol.Reply();r.success=v(root,"flag").equals("success");r.code=v(root,"code");r.message=v(root,"message");Element h=QimenProtocol.child(root,out?"deliveryOrder":"entryOrder");if(h==null)h=root;r.documentSn=v(h,out?"deliveryOrderCode":"entryOrderCode");r.externalOrder=v(h,out?"deliveryOrderId":"entryOrderId");r.status=v(h,"status");r.owner=v(h,"ownerCode");r.warehouse=v(h,"warehouseCode");return r;}
 public Map<String,Object> receipt(Map<String,Object>c,String secret,Map<String,String>p,String body){boolean out=p.get("method").endsWith("stockout.confirm");verify(c,secret,p,body,out?"stockout.confirm":"entryorder.confirm");Element root=QimenProtocol.parse(body),h=QimenProtocol.child(root,out?"deliveryOrder":"entryOrder");require(h!=null&&"request".equals(root.getTagName())&&(out?"DBCK":"DBRK").equals(v(h,out?"orderType":"entryOrderType")),"调拨必须使用原DBCK或DBRK类型");String status=v(h,"status"),confirm=v(h,"confirmType"),msg=v(h,"outBizCode");require((out?Arrays.asList("PARTDELIVERED","DELIVERED"):Arrays.asList("PARTFULFILLED","FULFILLED","CLOSED")).contains(status)&&Arrays.asList("0","1").contains(confirm),"请回传实际完成状态及最终或中间确认类型");boolean complete=confirm.equals("0");require(!(out?status.equals("DELIVERED"):Arrays.asList("FULFILLED","CLOSED").contains(status))||complete,"最终状态与中间确认矛盾");require(!msg.isEmpty()&&msg.length()<=128,"调拨增量回传须提供outBizCode");Element group=QimenProtocol.child(root,"orderLines");List<Element>original=group==null?Collections.emptyList():QimenProtocol.children(group,"orderLine");require(original.size()<=200&&(!original.isEmpty()||complete),"调拨回传明细无效");if(!v(h,"totalOrderLines").isEmpty())require(qty(v(h,"totalOrderLines"),false)==original.size(),"回传明细尚未完整，不能入账");List<Map<String,Object>>ls=new ArrayList<>();Set<String>seen=new HashSet<>();for(Element l:original){String no=v(l,"orderLineNo");require(!no.isEmpty()&&seen.add(no),"原行号缺失或重复");long actual=qty(v(l,"actualQty"),false),sum=0;Element bs=QimenProtocol.child(l,"batchs");List<Element>batches=bs==null?Collections.singletonList(l):QimenProtocol.children(bs,"batch");require(!batches.isEmpty(),"原行批次缺失");for(Element b:batches){String type=v(b,"inventoryType");require(Arrays.asList("ZP","CC").contains(type),"调拨只支持沿用原正品ZP或次品CC");long q=qty(v(b,"actualQty"),false);sum=Math.addExact(sum,q);ls.add(map("line_key",id(no),"sku_sn",v(l,"itemCode"),"batch_code",v(b,"batchCode"),"inventory_type",type.equals("CC")?"CP":"ZP","quantity",q,"owner_code",v(l,"ownerCode")));}require(actual==sum,"批次数量与原行实际数量不一致");}
  return map("document_sn",v(h,out?"deliveryOrderCode":"entryOrderCode"),"external_order",v(h,out?"deliveryOrderId":"entryOrderId"),"owner_code",v(h,"ownerCode"),"warehouse_code",v(h,"warehouseCode"),"message_id",msg,"complete",complete,"status",status,"carrier_code",v(h,"logisticsCode"),"waybill",v(h,"expressCode"),"lines",ls);
 }
 public Map<String,Object> inventory(String body,String warehouse,String owner,boolean paged){Element root=QimenProtocol.parse(body);require("response".equals(root.getTagName())&&"success".equals(v(root,"flag")),"库存查询未成功："+v(root,"message"));List<Map<String,Object>>ls=new ArrayList<>();Element group=QimenProtocol.child(root,"items");require(group!=null,"仓库缺少库存结果，不能按零处理");for(Element i:QimenProtocol.children(group,"item")){require(warehouse.equals(v(i,"warehouseCode"))&&(v(i,"ownerCode").isEmpty()||owner.equals(v(i,"ownerCode"))),"库存结果仓库或货主不匹配");String q=v(i,"quantity"),f=v(i,"lockQuantity");ls.add(map("sku_sn",v(i,"itemCode"),"batch_code",v(i,"batchCode"),"inventory_type",v(i,"inventoryType"),"physical",q.isEmpty()||f.isEmpty()?null:Math.addExact(qty(q,false),qty(f,false)),"unfrozen",q.isEmpty()?null:qty(q,false),"frozen",f.isEmpty()?null:qty(f,false)));}require(ls.size()<= (paged?100:1000),"库存返回行数超过接口上限");String total=v(root,"totalCount");return map("rows",ls,"total",total.isEmpty()?null:qty(total,false));}
 public Map<String,Object> inventoryReport(Map<String,Object>c,String secret,Map<String,String>p,String body){verify(c,secret,p,body,"inventory.report");Element root=QimenProtocol.parse(body);require("request".equals(root.getTagName()),"盘点通知结构无效");long pages=qty(v(root,"totalPage"),false),page=qty(v(root,"currentPage"),false),size=qty(v(root,"pageSize"),false);require(pages>=1&&pages<=1000&&page>=1&&page<=pages&&size<=1000&&Arrays.asList("CHECK","ADJUST").contains(v(root,"adjustType")),"盘点通知分页或类型无效");require(!v(root,"outBizCode").isEmpty()&&!v(root,"checkOrderCode").isEmpty(),"盘点通知消息和原单号必填");Element group=QimenProtocol.child(root,"items");require(group!=null,"盘点通知明细缺失");List<Map<String,Object>>ls=new ArrayList<>();for(Element i:QimenProtocol.children(group,"item"))ls.add(map("sku_sn",v(i,"itemCode"),"batch_code",v(i,"batchCode"),"inventory_type",v(i,"inventoryType"),"delta",qty(v(i,"quantity"),true),"total",v(i,"totalQty").isEmpty()?null:qty(v(i,"totalQty"),false)));require(ls.size()<=1000&&ls.size()<=size,"盘点通知行数超过分页范围");return map("message_id",v(root,"outBizCode")+"/"+page,"check_order",v(root,"checkOrderCode"),"owner_code",v(root,"ownerCode"),"warehouse_code",v(root,"warehouseCode"),"check_time",v(root,"checkTime"),"adjust_type",v(root,"adjustType"),"page",page,"pages",pages,"lines",ls);}
}
